using System.ComponentModel.DataAnnotations;

namespace Acme.Data;

public class Article
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Body { get; set; } = "";

    [Timestamp]
    public byte[] RowVersion { get; set; } = [];
}

using Microsoft.AspNetCore.Http.HttpResults;

app.MapPut("/articles/{id:int}", async Task<Results<NoContent, NotFound, Conflict>> (int id, ArticleUpdate input, BlogDbContext db) =>
{
    var article = await db.Articles.FindAsync(id);
    if (article is null) return TypedResults.NotFound();

    article.Title = input.Title;
    article.Body = input.Body;
    article.RowVersion = input.RowVersion;
    try
    {
        await db.SaveChangesAsync();
    }
    catch (DbUpdateConcurrencyException)
    {
        return TypedResults.Conflict();
    }
    return TypedResults.NoContent();
});

public record ArticleUpdate(string Title, string Body, byte[] RowVersion);

app.MapPut("/articles/{id:int}", async Task<Results<NoContent, NotFound, Conflict<Article>>> (int id, ArticleUpdate input, BlogDbContext db) =>
{
    var article = await db.Articles.FindAsync(id);
    if (article is null) return TypedResults.NotFound();

    article.Title = input.Title;
    article.Body = input.Body;
    db.Entry(article).Property(a => a.RowVersion).OriginalValue = input.RowVersion;
    try
    {
        await db.SaveChangesAsync();
    }
    catch (DbUpdateConcurrencyException ex)
    {
        var current = await ex.Entries.Single().GetDatabaseValuesAsync();
        if (current is null) return TypedResults.NotFound();
        return TypedResults.Conflict((Article)current.ToObject());
    }
    return TypedResults.NoContent();
});
